MW.hash=(x,y,s=0)=>{let n=Math.imul(x+71,374761393)^Math.imul(y+37,668265263)^Math.imul(s+17,1274126177);n=Math.imul(n^(n>>>13),1274126177);return(n^(n>>>16))>>>0;};
MW.makeWorld=function(region){const r=MW.regions[region],tile=MW.tile,w=MW.width,h=MW.height,terrain=new Uint8Array(w*h),decor=[],objects=[],npcs=[],homes=[];
 const path=(x,y)=>Math.abs(y-28)<=2||Math.abs(x-17)<=2||MW.landmarks.some(l=>Math.abs(x-l.x)<=1&&y>=Math.min(28,l.y)&&y<=Math.max(28,l.y));
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){const k=MW.hash(x,y,region);terrain[y*w+x]=path(x,y)?1:((x>32&&x<38&&y<24)||(x>44&&x<51&&y>35))?2:0;if(!path(x,y)&&x>1&&y>1&&x<w-2&&y<h-2&&terrain[y*w+x]!==2&&k%19===0&&!MW.landmarks.some(l=>Math.hypot(x-l.x,y-l.y)<4)&&!(x<21&&y>15&&y<40))decor.push({x:x*tile,y:y*tile,type:r.biome==='desert'?'cactus':r.biome==='mine'?'crystal':'tree',seed:k});}
 for(const b of [{x:4,y:21,w:4,h:4},{x:10,y:21,w:4,h:4},{x:5,y:34,w:5,h:4},{x:11,y:34,w:5,h:4}])homes.push({...b,x:b.x*tile,y:b.y*tile,w:b.w*tile,h:b.h*tile});
 const roles=['guide','shop','smith','side','side','tower'];const names=[r.npc,r.merchant,'铁匠 '+MW.npcNames[region],MW.npcNames[(region+3)%12],MW.npcNames[(region+7)%12],'문지기 월백'];
 [[11,25],[7,29],[12,31],[16,23],[16,33],[20,28]].forEach(([x,y],i)=>npcs.push({x:x*tile,y:y*tile,name:names[i].replace('铁匠','대장장이'),role:roles[i],color:['#c8b17b','#be81a1','#8a9ba5','#7bacc0','#a1b582','#c4a9d3'][i]}));
 MW.landmarks.forEach((l,i)=>objects.push({x:l.x*tile,y:l.y*tile,name:l.name,id:'land'+i,type:'landmark',index:i}));
 const locations=[[25,16],[31,21],[45,10],[54,19],[68,11],[69,36],[56,37],[42,44],[25,38],[62,47],[45,33],[30,8],[57,8],[70,45],[25,46],[62,31],[43,18],[54,47],[68,24],[28,32]];
 locations.forEach(([x,y],i)=>{terrain[y*w+x]=0;objects.push({x:x*tile,y:y*tile,name:r.item,id:'memory'+i,type:'memory',index:i});});
 for(let i=0;i<6;i++){const x=24+i*8,y=14+(i%3)*12;terrain[y*w+x]=0;objects.push({x:x*tile,y:y*tile,name:'잊힌 보물함',id:'chest'+i,type:'chest',index:i});}
 objects.push({x:74*tile,y:28*tile,name:'다음 지역',id:'exit',type:'portal',next:region+1});if(region>0)objects.push({x:3*tile,y:28*tile,name:'이전 지역',id:'back',type:'portal',next:region-1});
 for(const [x,y]of [[2,24],[2,32],[19,19],[19,37],[9,26]])decor.push({x:x*tile,y:y*tile,type:r.biome==='desert'?'cactus':r.biome==='mine'?'crystal':'tree',seed:region});npcs.push({x:15*tile,y:29*tile,name:'무기상 '+MW.npcNames[(region+5)%12],role:'weapons',color:'#b49b71'});const world={region,r,w,h,terrain,decor,objects,npcs,homes};world.solid=(x,y)=>{let tx=Math.floor(x/tile),ty=Math.floor(y/tile);if(tx<2||ty<2||tx>=w-2||ty>=h-2)return true;if(terrain[ty*w+tx]===2)return true;return homes.some(b=>x>b.x-8&&x<b.x+b.w+8&&y>b.y+40&&y<b.y+b.h-10)||decor.some(t=>Math.abs(x-t.x)<14&&Math.abs(y-t.y)<12);};world.path=path;return world;
};
MW.enemySpawns=[[26,27],[29,32],[31,16],[42,12],[45,24],[48,30],[52,17],[56,34],[60,12],[64,25],[68,33],[30,42],[42,40],[55,44],[69,43],[24,11],[46,47],[61,39],[72,14],[62,7],[39,19],[53,38],[31,37],[68,21]];
MW.makeInstance=function(region,floor){const w=MW.makeWorld(region);w.homes=[];w.npcs=[];w.decor=[];w.objects=[];w.terrain.fill(2);const cells=[[13,14],[35,14],[59,14],[13,37],[35,37],[59,37]];const carve=(x,y,ww,hh,t=0)=>{for(let yy=y;yy<y+hh;yy++)for(let xx=x;xx<x+ww;xx++)w.terrain[yy*w.w+xx]=t;};for(const [x,y]of cells){carve(x-7,y-7,15,15);for(let i=0;i<6;i++)w.decor.push({x:(x-6+i*2)*48,y:(y-6)*48,type:'crystal',seed:i});}carve(13,12,47,4,1);carve(13,35,47,4,1);carve(33,14,4,24,1);carve(11,14,4,24,1);carve(57,14,4,24,1);w.objects=cells.slice(1,4).map(([x,y],i)=>({x:x*48,y:y*48,id:'seal'+i,type:'landmark',index:i,name:['해의 봉인','달의 봉인','별의 봉인'][i]}));w.objects.push({x:13*48,y:14*48,id:'leave',type:'portal',name:'원정 귀환',next:region});w.rooms=cells;w.floor=floor;return w;};
